insert into public.lessons (id, topic, title, description, video_url, content, key_points, sort_order) values
  ('699db0a1297afea4b73d1049', 'Geography and Symbols', 'American Culture and Values', 'Understand the culture, values, and ideals that define America', 'https://www.youtube.com/embed/tMNQUp6UikU', 'American culture is diverse, reflecting the many people who have come from around the world. Certain values are widely cherished, including individualism, democracy, equality, and opportunity. Americans value freedom of speech, religion, and thought. Hard work and achievement are highly respected. The concept of ''the American Dream''—that anyone can succeed through hard work—is central to American identity.
insert into public.lesson_flashcards (id, lesson_id, term, definition, example) values
  ('69b703185c5f2c47940a8dc0', '699db0a1297afea4b73d1049', 'Nation of Immigrants', 'Description of the U.S. as a country built by people who came from all over the world', 'From the Pilgrims to today, waves of immigrants have shaped American culture and identity'),
  ('69b703185c5f2c47940a8dbf', '699db0a1297afea4b73d1049', 'Thanksgiving', 'National holiday celebrated on the fourth Thursday of November, giving thanks for blessings', 'Thanksgiving has been a national holiday since President Lincoln proclaimed it in 1863'),
  ('69b703185c5f2c47940a8dbe', '699db0a1297afea4b73d1049', 'American Dream', 'The belief that through hard work, anyone can achieve success and prosperity in the U.S.', 'Many immigrants come to America in pursuit of the American Dream'),
  ('69b703185c5f2c47940a8dbd', '699db0a1297afea4b73d1049', 'E Pluribus Unum', 'Latin for ''Out of many, one'' — the original U.S. motto representing unity from diversity', 'E Pluribus Unum appears on the Great Seal and on U.S. coins'),
  ('69b703185c5f2c47940a8dbc', '699db0a1297afea4b73d1048', 'Lincoln Memorial', 'Monument in Washington D.C. honoring President Abraham Lincoln', 'Martin Luther King Jr. gave his ''I Have a Dream'' speech at the Lincoln Memorial in 1963'),
  ('69b703185c5f2c47940a8dbb', '699db0a1297afea4b73d1048', 'Washington Monument', 'Tall obelisk in Washington D.C. honoring the first President, George Washington', 'At 555 feet tall, the Washington Monument was the world''s tallest structure when completed'),
  ('69b703185c5f2c47940a8dba', '699db0a1297afea4b73d1048', 'White House', 'The official residence and primary workplace of the President of the United States', 'Every U.S. President since John Adams has lived in the White House'),
  ('69b703185c5f2c47940a8db9', '699db0a1297afea4b73d1048', 'Washington D.C.', 'The capital of the United States, home to all three branches of the federal government', 'The White House, Capitol Building, and Supreme Court are all in Washington D.C.'),
  ('69b703185c5f2c47940a8db8', '699db0a1297afea4b73d1047', 'Appalachian Mountains', 'Mountain range running along the eastern United States', 'The Appalachian Trail stretches from Georgia to Maine through the Appalachian Mountains'),
  ('69b703185c5f2c47940a8db7', '699db0a1297afea4b73d1047', 'Great Lakes', 'The world''s largest freshwater lake system, located along the U.S.-Canada border', 'The five Great Lakes are Superior, Michigan, Huron, Erie, and Ontario'),
  ('69b703185c5f2c47940a8db6', '699db0a1297afea4b73d1047', 'Yellowstone', 'The first U.S. national park, established in 1872, known for geysers and wildlife', 'Old Faithful in Yellowstone is a famous geyser that erupts regularly'),
  ('69b703185c5f2c47940a8db5', '699db0a1297afea4b73d1047', 'Grand Canyon', 'A massive canyon in Arizona carved by the Colorado River, a famous national park', 'The Grand Canyon is over a mile deep and was formed over millions of years'),
  ('69b703185c5f2c47940a8db4', '699db0a1297afea4b73d1046', 'Rocky Mountains', 'Major mountain range running through the western United States', 'The Rocky Mountains include peaks in Colorado, Montana, and Wyoming'),
  ('69b703185c5f2c47940a8db3', '699db0a1297afea4b73d1046', 'Mississippi River', 'One of the two longest rivers in the U.S., running through the center of the country', 'The Mississippi River flows from Minnesota to the Gulf of Mexico'),
  ('69b703185c5f2c47940a8db2', '699db0a1297afea4b73d1046', 'Pacific Ocean', 'The ocean bordering the West Coast of the United States', 'Los Angeles, Seattle, and San Francisco are on the Pacific Coast'),
  ('69b703185c5f2c47940a8db1', '699db0a1297afea4b73d1046', 'Atlantic Ocean', 'The ocean bordering the East Coast of the United States', 'New York, Miami, and Boston are on the Atlantic Coast'),
  ('69b703185c5f2c47940a8db0', '699db0a1297afea4b73d1046', '50 States', 'The United States is made up of 50 states, each with its own government', 'Alaska and Hawaii were the last states added, both in 1959'),
  ('69b703185c5f2c47940a8daf', '699db0a1297afea4b73d1045', 'American Flag', 'National flag with 13 stripes (original colonies) and 50 stars (one per state)', 'The 50 stars represent the 50 states; a new star was added when Hawaii joined in 1960'),
  ('69b703185c5f2c47940a8dae', '699db0a1297afea4b73d1045', 'Liberty Bell', 'Historic bell in Philadelphia that symbolizes American independence and freedom', 'The Liberty Bell is displayed at Independence Hall in Philadelphia'),
  ('69b703185c5f2c47940a8dad', '699db0a1297afea4b73d1045', 'Statue of Liberty', 'Monument in New York Harbor symbolizing freedom and opportunity, gifted by France in 1886', 'The Statue of Liberty welcomed millions of immigrants arriving by ship'),
  ('69b703185c5f2c47940a8dac', '699db0a1297afea4b73d1045', 'Bald Eagle', 'National bird of the United States, symbolizing strength, courage, and independence', 'The Bald Eagle appears on the Great Seal and is protected by federal law'),
  ('69b703185c5f2c47940a8dab', '699db0a1297afea4b73d1044', 'Great Seal', 'Official symbol of the United States, featuring a bald eagle with an olive branch and arrows', 'The Great Seal appears on the back of the one-dollar bill'),
  ('69b703185c5f2c47940a8daa', '699db0a1297afea4b73d1044', 'Flag Etiquette', 'Rules for proper handling and display of the American flag', 'The flag should never touch the ground and is flown at half-staff to honor those who have died'),
  ('69b703185c5f2c47940a8da9', '699db0a1297afea4b73d1044', 'National Anthem', '''The Star-Spangled Banner,'' written in 1814, the official song of the United States', 'The National Anthem is played before major sporting events and national ceremonies'),
  ('69b703185c5f2c47940a8da8', '699db0a1297afea4b73d1044', 'Pledge of Allegiance', 'Oath of loyalty to the United States and its flag, often recited in schools', 'The Pledge of Allegiance ends with ''with liberty and justice for all'''),
  ('69b703185c5f2c47940a8da7', '699db0a1297afea4b73d1043', 'Pearl Harbor', 'Japanese attack on the U.S. naval base in Hawaii on December 7, 1941, causing the U.S. to enter WWII', 'President Roosevelt called December 7, 1941 ''a date which will live in infamy'''),
  ('69b703185c5f2c47940a8da6', '699db0a1297afea4b73d1043', 'Cold War', 'Period of political tension between the U.S. and Soviet Union from the 1940s to 1991', 'The space race between the U.S. and USSR was part of the Cold War'),
  ('69b703185c5f2c47940a8da5', '699db0a1297afea4b73d1043', 'World War II', 'Global war from 1939–1945; the U.S. entered after the attack on Pearl Harbor in 1941', 'D-Day in 1944 was the Allied invasion of Normandy, France that turned the tide of WWII'),
  ('69b703185c5f2c47940a8da4', '699db0a1297afea4b73d1043', 'World War I', 'Global war from 1914–1918; the U.S. entered in 1917 to help the Allies', 'Woodrow Wilson led the U.S. into WWI and proposed the League of Nations'),
  ('69b703185c5f2c47940a8da3', '699db0a1297afea4b73d1042', 'Segregation', 'Forced separation of people by race in public places, schools, and transportation', 'Before the Civil Rights Act, many Southern states had segregated schools and lunch counters'),
  ('69b703185c5f2c47940a8da2', '699db0a1297afea4b73d1042', 'Civil Rights Act of 1964', 'Law banning discrimination based on race, color, religion, sex, or national origin', 'The Civil Rights Act made it illegal to refuse service to someone based on their race'),
  ('69b703185c5f2c47940a8da1', '699db0a1297afea4b73d1042', 'Martin Luther King Jr.', 'Civil Rights leader known for nonviolent protest and his ''I Have a Dream'' speech', 'MLK led the 1963 March on Washington where he gave his famous speech'),
  ('69b703185c5f2c47940a8da0', '699db0a1297afea4b73d1042', 'Civil Rights Movement', 'Social movement in the 1950s–1960s to end racial segregation and discrimination', 'Rosa Parks and Martin Luther King Jr. were leaders of the Civil Rights Movement'),
  ('69b703185c5f2c47940a8d9f', '699db0a1297afea4b73d1041', '13th Amendment', 'Abolished slavery throughout the United States, ratified in 1865', 'The 13th Amendment permanently ended slavery after the Civil War'),
  ('69b703185c5f2c47940a8d9e', '699db0a1297afea4b73d1041', 'Emancipation Proclamation', '1863 order by Lincoln declaring enslaved people in Confederate states to be free', 'The Emancipation Proclamation was a turning point that made the Civil War about ending slavery'),
  ('69b703185c5f2c47940a8d9d', '699db0a1297afea4b73d1041', 'Abraham Lincoln', '16th President who led the Union through the Civil War and issued the Emancipation Proclamation', 'Lincoln''s Gettysburg Address described government ''of the people, by the people, for the people'''),
  ('69b703185c5f2c47940a8d9c', '699db0a1297afea4b73d1041', 'Civil War', 'War fought from 1861–1865 between the Union (North) and the Confederacy (South) over slavery', 'Over 600,000 soldiers died in the Civil War, making it the deadliest American conflict'),
  ('69b703185c5f2c47940a8d9b', '699db0a1297afea4b73d1040', 'Tribal Sovereignty', 'The right of Native American tribes to govern themselves as independent nations', 'Federally recognized tribes can establish their own laws and governments'),
  ('69b703185c5f2c47940a8d9a', '699db0a1297afea4b73d1040', 'Reservations', 'Areas of land set aside by the U.S. government for Native American tribes', 'Today, federally recognized tribes have sovereignty over their reservation lands'),
  ('69b703185c5f2c47940a8d99', '699db0a1297afea4b73d1040', 'Indian Removal Act', '1830 law that forced Native Americans to relocate west of the Mississippi River', 'President Andrew Jackson signed the Indian Removal Act in 1830'),
  ('69b703185c5f2c47940a8d98', '699db0a1297afea4b73d1040', 'Trail of Tears', 'Forced migration of Native Americans westward in the 1830s resulting in thousands of deaths', 'The Cherokee Nation was forced to walk over 1,000 miles, and many died'),
  ('69b703185c5f2c47940a8d97', '699db0a1297afea4b73d103f', '8th Amendment', 'Prohibits cruel and unusual punishment and excessive bail', 'Torturing a prisoner would violate the 8th Amendment'),
  ('69b703185c5f2c47940a8d96', '699db0a1297afea4b73d103f', 'Right to Counsel', 'The right to have an attorney, even if you cannot afford one', 'If you cannot afford a lawyer, the government must provide one for free'),
  ('69b703185c5f2c47940a8d95', '699db0a1297afea4b73d103f', 'Double Jeopardy', 'Protection against being tried twice for the same crime, guaranteed by the 5th Amendment', 'If found not guilty, you cannot be tried again for the same crime'),
  ('69b703185c5f2c47940a8d94', '699db0a1297afea4b73d103f', 'Innocent Until Proven Guilty', 'The presumption that accused persons are innocent until the government proves guilt', 'In the U.S., the prosecution must prove guilt beyond a reasonable doubt'),
  ('69b703185c5f2c47940a8d93', '699db0a1297afea4b73d103e', 'Civil Rights', 'Rights that protect individuals from discrimination and guarantee equal treatment', 'The Civil Rights Act of 1964 banned discrimination based on race, color, or religion'),
  ('69b703185c5f2c47940a8d92', '699db0a1297afea4b73d103e', 'Common Good', 'The shared benefit and welfare of the entire community', 'Public schools and fire departments exist for the common good'),
  ('69b703185c5f2c47940a8d91', '699db0a1297afea4b73d103e', 'Social Contract', 'The idea that citizens give up some freedoms in exchange for government protection of rights', 'We obey traffic laws (a limit on freedom) in exchange for safer roads for everyone'),
  ('69b703185c5f2c47940a8d90', '699db0a1297afea4b73d103d', 'Jury Duty', 'The obligation of citizens to serve on a jury when called upon by a court', 'Jury duty ensures that accused persons are judged by a group of their peers'),
  ('69b703185c5f2c47940a8d8f', '699db0a1297afea4b73d103d', 'Income Tax', 'Tax paid to the federal and state government on earnings from work', 'Americans file income tax returns each year, usually by April 15'),
  ('69b703185c5f2c47940a8d8e', '699db0a1297afea4b73d103d', 'Selective Service', 'System requiring men 18–25 to register in case a military draft is needed', 'Male citizens and residents must register with Selective Service at age 18'),
  ('69b703185c5f2c47940a8d8d', '699db0a1297afea4b73d103c', 'Permanent Resident', 'A non-citizen who has legal permission to live and work permanently in the U.S.', 'A green card holder is a permanent resident who can apply for citizenship after 5 years'),
  ('69b703185c5f2c47940a8d8c', '699db0a1297afea4b73d103c', 'Civic Duty', 'Obligations of citizens to their country, such as voting, jury service, and paying taxes', 'Serving on a jury is a civic duty that helps ensure fair trials'),
  ('69b703185c5f2c47940a8d8b', '699db0a1297afea4b73d103c', 'Naturalization', 'The legal process by which an immigrant becomes a U.S. citizen', 'After five years as a permanent resident, most immigrants can apply for naturalization'),
  ('69b703185c5f2c47940a8d8a', '699db0a1297afea4b73d103c', 'Citizen', 'A person who is a legal member of a country and has full rights and responsibilities', 'U.S. citizens can vote, run for office, and hold a U.S. passport'),
  ('69b703185c5f2c47940a8d89', '699db0a1297afea4b73d103b', 'Equal Protection', 'The 14th Amendment guarantee that laws apply equally to all people', 'Schools cannot be segregated because equal protection requires equal treatment'),
  ('69b703185c5f2c47940a8d88', '699db0a1297afea4b73d103b', 'Due Process', 'The right to fair legal procedures before the government can take away life, liberty, or property', 'You have the right to a lawyer and a fair trial under due process'),
  ('69b703185c5f2c47940a8d87', '699db0a1297afea4b73d103b', 'Freedom of Religion', 'The right to practice any religion, or no religion, without government interference', 'Americans can worship as Muslims, Christians, Jews, Hindus, or not at all'),
  ('69b703185c5f2c47940a8d86', '699db0a1297afea4b73d103b', 'Freedom of Speech', 'The right to express opinions without government censorship or retaliation', 'You can criticize government policies without fear of arrest due to freedom of speech'),
  ('69b703185c5f2c47940a8d85', '699db0a1297afea4b73d1039', 'Senate Confirmation', 'The Senate must approve presidential appointments to courts and Cabinet positions', 'Supreme Court nominees must be confirmed by a Senate vote'),
  ('69b703185c5f2c47940a8d84', '699db0a1297afea4b73d1039', 'Impeachment', 'The process where Congress formally charges a president or official with wrongdoing', 'The House impeaches and the Senate holds the trial to decide removal'),
  ('69b703185c5f2c47940a8d83', '699db0a1297afea4b73d1039', 'Checks and Balances', 'System where each branch of government can limit the power of the other branches', 'The President vetoes laws, Congress overrides vetoes, and courts strike down unconstitutional acts'),
  ('69b703185c5f2c47940a8d82', '699db0a1297afea4b73d1038', 'Lifetime Appointment', 'Federal judges serve until they die, retire, or are removed, ensuring independence', 'Supreme Court justices have lifetime appointments so they can rule without political pressure'),
  ('69b703185c5f2c47940a8d81', '699db0a1297afea4b73d1038', 'Chief Justice', 'The head of the Supreme Court and the federal judiciary', 'John Marshall was one of the most influential Chief Justices in U.S. history'),
  ('69b703185c5f2c47940a8d80', '699db0a1297afea4b73d1038', 'Judicial Review', 'The Supreme Court''s power to declare laws unconstitutional', 'In Marbury v. Madison, the Supreme Court established the power of judicial review. The Supreme Court used judicial review to overturn segregation laws.'),
  ('69b703185c5f2c47940a8d7f', '699db0a1297afea4b73d1038', 'Supreme Court', 'The highest court in the U.S., with nine justices and final authority on constitutional questions', 'The Supreme Court''s rulings set legal precedents for all lower courts'),
  ('69b703185c5f2c47940a8d7e', '699db0a1297afea4b73d1037', '22nd Amendment', 'Limits the President to a maximum of two terms in office', 'FDR served four terms, which led to the 22nd Amendment limiting future presidents to two'),
  ('69b703185c5f2c47940a8d7d', '699db0a1297afea4b73d1037', 'Presidential Veto', 'The President''s power to reject legislation passed by Congress', 'A President can veto a bill they disagree with, sending it back to Congress. Congress can override a presidential veto with a two-thirds majority vote.'),
  ('69b703185c5f2c47940a8d7c', '699db0a1297afea4b73d1037', 'Cabinet', 'Group of department heads who advise the President and manage executive departments', 'The Secretary of State and Secretary of Defense are Cabinet members'),
  ('69b703185c5f2c47940a8d7b', '699db0a1297afea4b73d1037', 'President', 'Head of the Executive Branch, elected to four-year terms, limited to two terms', 'The President signs bills into law and is commander-in-chief of the military'),
  ('69b703185c5f2c47940a8d7a', '699db0a1297afea4b73d1036', 'Capitol Building', 'The building in Washington, D.C. where Congress meets', 'Both the Senate and House of Representatives meet in the Capitol Building'),
  ('69b703185c5f2c47940a8d79', '699db0a1297afea4b73d1036', 'Veto Override', 'Congress can reverse a presidential veto with a two-thirds vote in both chambers', 'If the President vetoes a bill, Congress can still pass it with enough votes'),
  ('69b703185c5f2c47940a8d78', '699db0a1297afea4b73d1036', 'House of Representatives', 'Lower chamber of Congress with 435 members based on state population, serving 2-year terms', 'California has many more House members than Wyoming because it has more people'),
  ('69b703185c5f2c47940a8d77', '699db0a1297afea4b73d1036', 'Senate', 'Upper chamber of Congress with 100 members, two from each state, serving 6-year terms', 'There are always exactly 100 senators, regardless of state population'),
  ('69b703185c5f2c47940a8d76', '699db0a1297afea4b73d1035', 'Rule of Law', 'The principle that everyone, including government officials, must follow the law', 'Even the President must obey the law — no one is above it'),
  ('69b703185c5f2c47940a8d75', '699db0a1297afea4b73d1035', 'Separation of Powers', 'Division of government into three branches: legislative, executive, and judicial', 'Congress makes laws, the President enforces them, and courts interpret them'),
  ('69b703185c5f2c47940a8d74', '699db0a1297afea4b73d1035', 'Federalism', 'Division of power between the national government and state governments', 'Education is mainly controlled by states, while national defense is federal'),
  ('69b703185c5f2c47940a8d73', '699db0a1297afea4b73d1035', 'Democratic Republic', 'A system where citizens elect representatives to govern on their behalf', 'The U.S. is a democratic republic — citizens vote for senators and representatives'),
  ('69b703185c5f2c47940a8d72', '699db0a1297afea4b73d1034', '26th Amendment', 'Lowered the voting age from 21 to 18, ratified in 1971', 'Young people who served in Vietnam pushed for the 26th Amendment'),
  ('69b703185c5f2c47940a8d71', '699db0a1297afea4b73d1034', 'Voting Rights Act', '1965 federal law that eliminated literacy tests and other barriers to voting', 'The Voting Rights Act was passed during the Civil Rights Movement to protect African American voters'),
  ('69b703185c5f2c47940a8d70', '699db0a1297afea4b73d1034', '19th Amendment', 'Granted women the right to vote, ratified in 1920', 'Susan B. Anthony was a key leader in the fight that led to the 19th Amendment'),
  ('69b703185c5f2c47940a8d6f', '699db0a1297afea4b73d1034', '15th Amendment', 'Prohibited voting discrimination based on race, ratified in 1870', 'The 15th Amendment gave African American men the right to vote after the Civil War'),
  ('69b703185c5f2c47940a8d6e', '699db0a1297afea4b73d1033', 'Fourth Amendment', 'Protects against unreasonable searches and seizures by the government', 'Police generally need a warrant to search your home under the Fourth Amendment'),
  ('69b703185c5f2c47940a8d6d', '699db0a1297afea4b73d1033', 'Second Amendment', 'Protects the right of the people to keep and bear arms', 'The Second Amendment has been the subject of many Supreme Court decisions'),
  ('69b703185c5f2c47940a8d6c', '699db0a1297afea4b73d1033', 'Civil Liberties', 'Freedoms guaranteed by law that protect individuals from government overreach', 'Free speech and the right to a fair trial are civil liberties protected by the Constitution'),
  ('69b703185c5f2c47940a8d6b', '699db0a1297afea4b73d1033', 'First Amendment', 'Protects freedom of speech, religion, press, assembly, and petition', 'The First Amendment allows people to criticize the government without being arrested'),
  ('69b703185c5f2c47940a8d6a', '699db0a1297afea4b73d1032', 'Revolutionary War', 'War fought from 1775–1783 in which the American colonies won independence from Britain', 'George Washington commanded the Continental Army during the Revolutionary War'),
  ('69b703185c5f2c47940a8d69', '699db0a1297afea4b73d1032', 'Independence Day', 'National holiday on July 4th celebrating the signing of the Declaration of Independence', 'Americans celebrate Independence Day with fireworks and parades'),
  ('69b703185c5f2c47940a8d68', '699db0a1297afea4b73d1032', 'Thomas Jefferson', 'Founding Father and primary author of the Declaration of Independence', 'Jefferson declared ''all men are created equal'' in the Declaration'),
  ('69b703185c5f2c47940a8d67', '699db0a1297afea4b73d1032', 'Declaration of Independence', 'Document adopted on July 4, 1776 declaring the colonies'' independence from Britain', 'Thomas Jefferson wrote most of the Declaration of Independence'),
  ('69b703185c5f2c47940a8d66', '699db0a1297afea4b73d1031', 'Articles of Confederation', 'The first governing document of the U.S., replaced by the Constitution because it was too weak', 'Under the Articles, Congress had no power to levy taxes or enforce laws'),
  ('69b703185c5f2c47940a8d65', '699db0a1297afea4b73d1031', 'Ratification', 'The process of formal state approval required for the Constitution to take effect', 'The Constitution was ratified by nine states in 1788 and went into effect in 1789.'),
  ('69b703185c5f2c47940a8d64', '699db0a1297afea4b73d1031', 'Bill of Rights', 'The first ten amendments to the Constitution, protecting fundamental individual freedoms', 'The Bill of Rights guarantees freedom of speech, religion, and the right to a fair trial'),
  ('69b703185c5f2c47940a8d63', '699db0a1297afea4b73d1031', 'James Madison', 'Called the ''Father of the Constitution'' for his central role in drafting it', 'Madison came prepared with the Virginia Plan, which formed the basis of the Constitution'),
  ('69b703185c5f2c47940a8d62', '699db0a1297afea4b73d1031', 'Constitutional Convention', 'Meeting of 55 delegates in Philadelphia in 1787 to draft the U.S. Constitution', 'James Madison and Benjamin Franklin were key delegates at the Constitutional Convention'),
  ('699db0b8297afea4b73d105d', '699db0a1297afea4b73d1038', 'Judicial Branch', 'Supreme Court and federal courts that interpret laws', 'The Supreme Court can declare laws unconstitutional'),
  ('699db0b8297afea4b73d105b', '699db0a1297afea4b73d1037', 'Executive Branch', 'Led by President, enforces laws and manages government', 'The President commands the military and appoints cabinet members'),
  ('699db0b8297afea4b73d1058', '699db0a1297afea4b73d1036', 'Legislative Branch', 'Congress (Senate and House) that makes federal laws', 'The Legislative Branch passes laws that affect the entire nation'),
  ('699db0b8297afea4b73d1057', '699db0a1297afea4b73d1041', 'George Washington', 'Commander of Continental Army and first President of the United States', 'George Washington led the American forces to victory against the British'),
  ('699db0b8297afea4b73d1056', '699db0a1297afea4b73d1041', 'Boston Tea Party', '1773 protest where colonists dumped British tea into Boston Harbor', 'The Boston Tea Party was a response to taxes imposed without colonial representation'),
  ('699db0b8297afea4b73d1055', '699db0a1297afea4b73d1041', 'Revolutionary War', 'Conflict from 1775-1783 resulting in American independence from Britain', 'George Washington commanded the Continental Army during the Revolutionary War'),
  ('699db0b8297afea4b73d1054', '699db0a1297afea4b73d1041', 'Declaration of Independence', 'Document adopted July 4, 1776, declaring American independence from Britain', 'Thomas Jefferson wrote the Declaration stating that all men are created equal');
insert into public.community_resources (id, name, category, services, address, city, state, zip, latitude, longitude, location_precision, phone, website, logo_url, hours, languages, cost, description, source, source_url, last_verified, external_id, relevance_note, is_active) values
  ('6ad93c676787fcfee6c43ee3', 'De Novo', 'legal', array['legal']::text[], '47 Thorndike Street, Suite SB-LL-1', 'Cambridge', 'MA', '02050', 42.115, -70.71, 'zip', '(617) 661-1010', 'https://www.denovo.org/', '', '', array['Spanish', 'French', 'Farsi']::text[], '', 'DOJ-recognized organization. Its accredited representatives can give immigration legal help. Call to ask about services and cost.', 'DOJ EOIR Recognized Organizations roster (by state and city, updated 10/18/26)', 'https://www.justice.gov/eoir/recognition-accreditation-roster-reports', '2026-10-21', 'doj:de-novo-47-thorndike-street-suite-sb-ll-1-02050', '', true),
  ('6ad93c676787fcfee6c43ee2', 'Santa Barbara County Immigrant Legal Defense Center', 'legal', array['legal']::text[], '1136 E. Montecito Street', 'Santa Barbara', 'CA', '91303', 34.198, -118.602, 'zip', '(805) 886-9136', 'https://www.sbimmigrantdefense.org/', 'https://static.wixstatic.com/media/96c383_4ef40a818f1445ec837a7ffb48aa9e45~mv2.png/v1/fill/w_122,h_112,al_c,q_85,usm_0.66_1.00_0.01,enc_avif,quality_auto/ILDC%20Logo%20(Transparent0_edited.png', '', array['Spanish', 'Mixteco']::text[], '', 'DOJ-recognized organization. Its accredited representatives can give immigration legal help. Call to ask about services and cost.', 'DOJ EOIR Recognized Organizations roster (by state and city, updated 10/18/26)', 'https://www.justice.gov/eoir/recognition-accreditation-roster-reports', '2026-10-21', 'doj:santa-barbara-county-immigrant-legal-defense-center-1136-e-montecito-street-91303', '', true),
